package br.com.studyou.data.repository

import br.com.studyou.domain.model.GeneratedGames
import java.util.concurrent.ConcurrentHashMap

/**
 * In-memory cache of the games generated by the backend for each of the signed-in user's
 * files, keyed by the file's backend id. Filled by [FileRepositoryImpl] (after an upload or a
 * refresh from the backend) and read by [GameRepositoryImpl]. Cleared when the user logs out.
 */
class GeneratedGamesStore {
    private val games = ConcurrentHashMap<String, GeneratedGames>()

    fun put(fileId: String, generatedGames: GeneratedGames) {
        games[fileId] = generatedGames
    }

    fun get(fileId: String): GeneratedGames? = games[fileId]

    fun clear() = games.clear()
}
